<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое РКМ по гособоронзаказу?", "acceptedAnswer": {"@type": "Answer", "text": "Расчётно-калькуляционные материалы — комплект документов, обосновывающих цену продукции ГОЗ: калькуляции, расшифровки затрат, расчёты трудоёмкости, оплаты труда и прибыли. В действующем приказе ФАС № 995/22 называются обосновывающими документами."}}, {"@type": "Question", "name": "Каким документом утверждены формы РКМ?", "acceptedAnswer": {"@type": "Answer", "text": "Приказом ФАС России от 16.12.2022 № 995/22 (зарегистрирован Минюстом 30.12.2022, действует с 10.01.2023, актуальная редакция — от 18.12.2025). Он заменил приказ ФАС № 1138/19."}}, {"@type": "Question", "name": "Какие формы заполнять обязательно?", "acceptedAnswer": {"@type": "Answer", "text": "Универсального списка нет: состав зависит от вида цены, метода её определения и запроса заказчика или ВП. Базовый костяк — плановая калькуляция (ф. 2), расшифровки материальных затрат, расчёт трудоёмкости (ф. 23), зарплатные формы, расчёт прибыли (ф. 20) и пояснительная записка."}}, {"@type": "Question", "name": "Что такое привнесённые и собственные затраты?", "acceptedAnswer": {"@type": "Answer", "text": "Привнесённые — покупные ресурсы (материалы, ПКИ, работы соисполнителей), собственные — создаваемые предприятием (зарплата, взносы, накладные, амортизация). Формы № 995/22 требуют раскрывать себестоимость в этом разрезе."}}, {"@type": "Question", "name": "Как нормируется прибыль в РКМ?", "acceptedAnswer": {"@type": "Answer", "text": "По Положению № 1465: плановая прибыль не более 1 % привнесённых затрат плюс 25 % собственных. База раскрывается в форме № 20 — поэтому структура затрат напрямую влияет на допустимую прибыль."}}, {"@type": "Question", "name": "Кому направляются РКМ?", "acceptedAnswer": {"@type": "Answer", "text": "Государственному заказчику вместе с предложением о цене; по продукции, закреплённой за военными представительствами, — в ВП Минобороны для заключения о цене. Внутри кооперации РКМ запрашивает головной исполнитель у соисполнителей."}}, {"@type": "Question", "name": "Чем грозят РКМ на устаревших формах?", "acceptedAnswer": {"@type": "Answer", "text": "Возвратом комплекта и затягиванием согласования цены: проверяющие работают по действующей редакции № 995/22, и формы приказа 1138/19 не принимаются."}}, {"@type": "Question", "name": "Нужны ли РКМ соисполнителю нижнего уровня?", "acceptedAnswer": {"@type": "Answer", "text": "Да, принцип обоснования цены действует по всей кооперации: головной исполнитель проверяет цены соисполнителей и вправе запросить их обосновывающие документы."}}, {"@type": "Question", "name": "Чем отличается плановая калькуляция от отчётной?", "acceptedAnswer": {"@type": "Answer", "text": "Плановая (ф. 2) — ожидаемые затраты при формировании цены; отчётная (ф. 3) — фактические затраты по данным раздельного учёта после исполнения. Их сопоставление — основа перевода ориентировочной цены в фиксированную."}}, {"@type": "Question", "name": "Какие затраты нельзя включать в цену ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Не связанные с производством продукции и не предусмотренные порядком Минпромторга № 334 — например, расходы сверх установленных норм. Каждую статью калькуляции стоит проверять на включаемость по приказу № 334."}}, {"@type": "Question", "name": "Что писать в пояснительной записке?", "acceptedAnswer": {"@type": "Answer", "text": "Метод определения цены, источники цен и норм по каждой значимой строке, обоснование нормативов накладных расходов и прибыли, отличия от предыдущих калькуляций. Записка с конкретикой резко сокращает количество запросов."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как подготовить РКМ по гособоронзаказу", "inLanguage": "ru-RU", "step": [
{"@type": "HowToStep", "position": 1, "name": "Определить вид цены и метод", "text": "По Положению № 1465 определить вид цены контракта и метод её определения — от этого зависит состав форм."},
{"@type": "HowToStep", "position": 2, "name": "Собрать исходные данные", "text": "Нормы расхода, цены материалов, договоры соисполнителей, трудоёмкость, тарифные ставки, нормативы накладных расходов, данные раздельного учёта."},
{"@type": "HowToStep", "position": 3, "name": "Рассчитать трудоёмкость и оплату труда", "text": "Заполнить форму 23 и зарплатные формы на основе техпроцессов и действующих норм."},
{"@type": "HowToStep", "position": 4, "name": "Заполнить расшифровки материальных затрат", "text": "Каждая позиция — с ценой и документальным подтверждением; цены соисполнителей обосновываются их РКМ."},
{"@type": "HowToStep", "position": 5, "name": "Собрать калькуляцию и прибыль", "text": "Свести статьи в форму 2 с разделением затрат на привнесённые и собственные, рассчитать прибыль в форме 20."},
{"@type": "HowToStep", "position": 6, "name": "Подготовить записку и провести сверку", "text": "Написать пояснительную записку с источниками по каждой строке и сверить итоги всех форм перед отправкой заказчику или в ВП."}
]}
</script>
